 result['plans']['strong_simplification']=dict(actions=e0,notes=T('Standing E0 route omits optional new-grant and duplicated source queries, plus a redundant partner confirmation message already conveyed by actual replacement acceptance.|既有E0路线省可选新许可和重复资料查询，并省已由实际替换接收传达的重复合作方确认。'),failed_goals={})
